import type { ReactElement } from "react"
import type { FieldOption } from "../field/field-types"

import { cn } from "@/lib/utils"

export function ComboboxOptionRow({
  option,
  truncateLabel = true,
}: {
  option: FieldOption
  /** False inside the open list so the popover can grow to fit labels. */
  truncateLabel?: boolean
}): ReactElement {
  const Icon = option.icon
  return (
    <span className={cn("flex items-center gap-2", truncateLabel ? "min-w-0" : "min-w-max")}>
      {Icon ? (
        <Icon
          className="size-3.5 shrink-0 text-muted-foreground"
          aria-hidden
        />
      ) : null}
      <span className={cn(truncateLabel ? "truncate" : "whitespace-nowrap")}>{option.label}</span>
    </span>
  )
}

import { AlertCircle } from "lucide-react"

type ComboboxOptionsErrorProps = {
  message: string
}

export function ComboboxOptionsError({ message }: ComboboxOptionsErrorProps) {
  return (
    <div className="flex items-start gap-2 px-3 py-4 text-destructive text-xs">
      <AlertCircle
        className="mt-0.5 size-3.5 shrink-0"
        aria-hidden
      />
      <span>{message}</span>
    </div>
  )
}

import type { ReactNode } from "react"

const SKELETON_KEYS = ["a", "b", "c", "d"] as const

export function ComboboxOptionsSkeleton(): ReactNode {
  return (
    <div className="flex flex-col gap-1.5 p-2">
      {SKELETON_KEYS.map((key) => (
        <div
          key={key}
          className="h-7 w-full animate-pulse rounded-md bg-muted"
        />
      ))}
    </div>
  )
}

import type { FieldOption } from "../field/field-types"

export function optionSearchValue(option: FieldOption): string {
  const labelText = typeof option.label === "string" ? option.label : String(option.value)
  return [labelText, option.value, option.keywords].filter(Boolean).join(" ")
}

/** Keep a stored value visible when it is missing from the current option catalog. */
export function optionsIncluding(options: FieldOption[], value: string): FieldOption[] {
  if (!value || options.some((option) => String(option.value) === value)) return options
  return [...options, { value, label: value, keywords: value }]
}

"use client"

import type { ReactNode } from "react"
import type { FieldSize } from "../constants"
import type { FieldOption } from "../field/field-types"

import { ChevronsUpDownIcon, XIcon } from "lucide-react"
import { useMemo, useState } from "react"

import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import Spinner from "@/components/ui/spinner"
import { COMBOBOX_POPOVER_CONTENT_CLASS } from "@/lib/combobox-popover"
import { MULTI_SELECT_VALUE_BADGE_CLASS } from "@/lib/multi-select-badge"
import { cn } from "@/lib/utils"

import { FIELD_CONTROL_HEIGHT_CLASS } from "../constants"
import { FieldSelectionFooter } from "../field/field-clear-selection-footer"
import { ComboboxOptionsError } from "./combobox-options-error"
import { ComboboxOptionsSkeleton } from "./combobox-options-skeleton"
import { optionSearchValue } from "./combobox-utils"

export type SearchableMultiSelectProps = {
  options: FieldOption[]
  value: string[]
  onValueChange: (value: string[]) => void
  placeholder?: string
  searchPlaceholder?: string
  emptyMessage?: string
  noResultsMessage?: string
  optionsError?: string
  loading?: boolean
  disabled?: boolean
  selectAll?: boolean
  selectAllLabel?: string
  clearable?: boolean
  clearLabel?: string
  maxSelected?: number
  showSelectedCount?: boolean
  showSelectedValues?: boolean
  className?: string
  contentClassName?: string
  id?: string
  invalid?: boolean
  required?: boolean
  "aria-label"?: string
  modal?: boolean
  size?: FieldSize
  open?: boolean
  onOpenChange?: (open: boolean) => void
  shouldFilter?: boolean
  commandInputValue?: string
  onCommandInputValueChange?: (value: string) => void
}

function asStringArray(value: string[]): string[] {
  return value.map(String)
}

export function SearchableMultiSelect({
  options,
  value,
  onValueChange,
  placeholder = "Select…",
  searchPlaceholder = "Search…",
  emptyMessage = "No options available.",
  noResultsMessage = "No results found.",
  optionsError,
  loading = false,
  disabled = false,
  selectAll = false,
  selectAllLabel,
  clearable = false,
  clearLabel,
  maxSelected,
  showSelectedCount = false,
  showSelectedValues = false,
  className,
  contentClassName,
  id,
  invalid,
  required,
  "aria-label": ariaLabel,
  modal,
  size = "default",
  open: controlledOpen,
  onOpenChange: controlledOnOpenChange,
  shouldFilter = true,
  commandInputValue,
  onCommandInputValueChange,
}: SearchableMultiSelectProps) {
  const [uncontrolledOpen, setUncontrolledOpen] = useState(false)
  const open = controlledOpen ?? uncontrolledOpen
  const setOpen = controlledOnOpenChange ?? setUncontrolledOpen

  const selected = asStringArray(value)
  const selectedOptions = useMemo(
    () => options.filter((option) => selected.includes(String(option.value))),
    [options, selected],
  )
  const atMax = maxSelected !== undefined && selected.length >= maxSelected
  const isDisabled = disabled || loading
  const hasError = Boolean(optionsError)

  const selectableValues = options.filter((option) => !option.disabled).map((option) => String(option.value))

  const toggle = (nextValue: string) => {
    if (isDisabled) return
    if (selected.includes(nextValue)) {
      onValueChange(selected.filter((item) => item !== nextValue))
      return
    }
    if (atMax) return
    onValueChange([...selected, nextValue])
  }

  const clear = () => {
    if (isDisabled) return
    onValueChange([])
  }

  const selectAllValues = () => {
    if (isDisabled) return
    const capped = maxSelected !== undefined ? selectableValues.slice(0, maxSelected) : selectableValues
    onValueChange(capped)
  }

  const allSelected = selectableValues.length > 0 && selectableValues.every((entry) => selected.includes(entry))
  const showSelectAllFooter = selectAll && !allSelected && selectableValues.length > 0 && !hasError
  const showClearFooter = clearable && selected.length > 0 && !hasError

  const triggerContent: ReactNode =
    selected.length === 0
      ? placeholder
      : showSelectedCount
        ? `${selected.length} selected`
        : selectedOptions.map((option) => option.label).join(", ")

  return (
    <>
      <Popover
        {...(modal !== undefined ? { modal } : {})}
        open={open}
        onOpenChange={(next) => {
          if (isDisabled) return
          setOpen(next)
        }}>
        <PopoverTrigger asChild>
          <Button
            id={id}
            type="button"
            variant="outline"
            role="combobox"
            disabled={isDisabled}
            aria-invalid={invalid}
            {...(required !== undefined ? { "aria-required": required } : {})}
            aria-expanded={open}
            aria-busy={loading || undefined}
            aria-label={ariaLabel}
            data-field-name={id}
            className={cn(
              FIELD_CONTROL_HEIGHT_CLASS[size],
              "w-full justify-between font-normal",
              selected.length === 0 && "text-muted-foreground",
              className,
            )}>
            <span className="flex min-w-0 flex-1 items-center gap-2 truncate">
              {loading ? <Spinner className="size-3.5 shrink-0" /> : null}
              {triggerContent}
            </span>
            <ChevronsUpDownIcon className="opacity-50" />
          </Button>
        </PopoverTrigger>
        <PopoverContent
          className={cn(COMBOBOX_POPOVER_CONTENT_CLASS, contentClassName)}
          align="start">
          <Command shouldFilter={shouldFilter}>
            <CommandInput
              placeholder={searchPlaceholder}
              {...(commandInputValue !== undefined ? { value: commandInputValue } : {})}
              {...(onCommandInputValueChange ? { onValueChange: onCommandInputValueChange } : {})}
            />
            <CommandList>
              {hasError ? (
                <ComboboxOptionsError message={optionsError ?? ""} />
              ) : loading ? (
                <ComboboxOptionsSkeleton />
              ) : options.length === 0 ? (
                <div className="px-3 py-6 text-center text-muted-foreground text-xs">{emptyMessage}</div>
              ) : (
                <>
                  <CommandEmpty>{noResultsMessage}</CommandEmpty>
                  <CommandGroup>
                    {options.map((option) => {
                      const optionValue = String(option.value)
                      const isSelected = selected.includes(optionValue)
                      return (
                        <CommandItem
                          key={optionValue}
                          value={optionSearchValue(option)}
                          disabled={option.disabled || (!isSelected && atMax)}
                          onSelect={() => toggle(optionValue)}>
                          <Checkbox
                            checked={isSelected}
                            className="pointer-events-none mr-2"
                            tabIndex={-1}
                            aria-hidden
                          />
                          <span className="whitespace-nowrap">{option.label}</span>
                        </CommandItem>
                      )
                    })}
                  </CommandGroup>
                </>
              )}
            </CommandList>
            {showSelectAllFooter || showClearFooter ? (
              <FieldSelectionFooter
                {...(showSelectAllFooter
                  ? {
                      selectAllLabel,
                      onSelectAll: selectAllValues,
                    }
                  : {})}
                {...(showClearFooter
                  ? {
                      clearLabel,
                      onClear: clear,
                    }
                  : {})}
              />
            ) : null}
          </Command>
        </PopoverContent>
      </Popover>
      {showSelectedValues && selectedOptions.length > 0 ? (
        <div className="flex flex-wrap gap-1">
          {selectedOptions.map((option) => (
            <Badge
              key={String(option.value)}
              variant="default"
              className={MULTI_SELECT_VALUE_BADGE_CLASS}>
              {option.label}
              {clearable && !isDisabled ? (
                <button
                  type="button"
                  className="rounded-sm outline-none focus-visible:ring-2"
                  onClick={() => toggle(String(option.value))}
                  aria-label={`Remove ${String(option.label)}`}>
                  <XIcon className="size-3" />
                </button>
              ) : null}
            </Badge>
          ))}
        </div>
      ) : null}
    </>
  )
}

"use client"

import type { LucideIcon } from "lucide-react"
import type { ReactNode } from "react"
import type { FieldSize } from "../constants"
import type { FieldOption } from "../field/field-types"

import { CheckIcon, ChevronsUpDownIcon } from "lucide-react"
import { useMemo, useState } from "react"

import { Button } from "@/components/ui/button"
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import Spinner from "@/components/ui/spinner"
import { COMBOBOX_POPOVER_CONTENT_CLASS } from "@/lib/combobox-popover"
import { cn } from "@/lib/utils"

import { FIELD_CONTROL_HEIGHT_CLASS } from "../constants"
import { FieldClearSelectionFooter } from "../field/field-clear-selection-footer"
import { ComboboxOptionRow } from "./combobox-option-row"
import { ComboboxOptionsError } from "./combobox-options-error"
import { ComboboxOptionsSkeleton } from "./combobox-options-skeleton"
import { optionSearchValue } from "./combobox-utils"

export type SearchableSelectProps = {
  options: FieldOption[]
  value?: string
  onValueChange: (value: string) => void
  onClear?: () => void
  placeholder?: string
  searchPlaceholder?: string
  emptyMessage?: string
  noResultsMessage?: string
  optionsError?: string
  loading?: boolean
  disabled?: boolean
  clearable?: boolean
  clearLabel?: string
  className?: string
  contentClassName?: string
  id?: string
  invalid?: boolean
  required?: boolean
  "aria-label"?: string
  modal?: boolean
  size?: FieldSize
  icon?: LucideIcon
  open?: boolean
  onOpenChange?: (open: boolean) => void
  /** When set, used as the trigger label instead of the selected option label. */
  displayValue?: ReactNode
  shouldFilter?: boolean
  commandInputValue?: string
  onCommandInputValueChange?: (value: string) => void
}

function TriggerIcon({ icon: Icon, loading }: { icon?: LucideIcon; loading: boolean }) {
  if (loading) {
    return <Spinner className="size-3.5 shrink-0" />
  }

  if (!Icon) return null

  return (
    <Icon
      className="size-3.5 shrink-0 text-muted-foreground"
      aria-hidden
    />
  )
}

export function SearchableSelect({
  options,
  value = "",
  onValueChange,
  onClear,
  placeholder = "Select…",
  searchPlaceholder = "Search…",
  emptyMessage = "No options available.",
  noResultsMessage = "No results found.",
  optionsError,
  loading = false,
  disabled = false,
  clearable = false,
  clearLabel,
  className,
  contentClassName,
  id,
  invalid,
  required,
  "aria-label": ariaLabel,
  modal,
  size = "default",
  icon,
  open: controlledOpen,
  onOpenChange: controlledOnOpenChange,
  displayValue,
  shouldFilter = true,
  commandInputValue,
  onCommandInputValueChange,
}: SearchableSelectProps) {
  const [uncontrolledOpen, setUncontrolledOpen] = useState(false)
  const open = controlledOpen ?? uncontrolledOpen
  const setOpen = controlledOnOpenChange ?? setUncontrolledOpen

  const current = value == null || value === "" ? "" : String(value)
  const selected = useMemo(() => options.find((option) => String(option.value) === current), [current, options])
  const isDisabled = disabled || loading
  const hasError = Boolean(optionsError)
  const showClearFooter = clearable && current && !hasError

  const clear = () => {
    if (isDisabled) return
    if (onClear) {
      onClear()
    } else {
      onValueChange("")
    }
    setOpen(false)
  }

  const triggerLabel = displayValue ?? (selected ? <ComboboxOptionRow option={selected} /> : placeholder)

  return (
    <Popover
      {...(modal !== undefined ? { modal } : {})}
      open={open}
      onOpenChange={(next) => {
        if (isDisabled) return
        setOpen(next)
      }}>
      <PopoverTrigger asChild>
        <Button
          id={id}
          type="button"
          variant="outline"
          role="combobox"
          disabled={isDisabled}
          aria-invalid={invalid}
          {...(required !== undefined ? { "aria-required": required } : {})}
          aria-expanded={open}
          aria-busy={loading || undefined}
          aria-label={ariaLabel}
          data-field-name={id}
          className={cn(
            FIELD_CONTROL_HEIGHT_CLASS[size],
            "w-full justify-between px-2 font-normal",
            !selected && !displayValue && "text-muted-foreground",
            className,
          )}>
          <span className="flex min-w-0 flex-1 items-center gap-2 truncate">
            <TriggerIcon
              {...(icon ? { icon } : {})}
              loading={loading}
            />
            {triggerLabel}
          </span>
          <ChevronsUpDownIcon className="size-3.5 shrink-0 opacity-50" />
        </Button>
      </PopoverTrigger>
      <PopoverContent
        className={cn(COMBOBOX_POPOVER_CONTENT_CLASS, contentClassName)}
        align="start">
        <Command shouldFilter={shouldFilter}>
          <CommandInput
            placeholder={searchPlaceholder}
            {...(commandInputValue !== undefined ? { value: commandInputValue } : {})}
            {...(onCommandInputValueChange ? { onValueChange: onCommandInputValueChange } : {})}
          />
          <CommandList>
            {hasError ? (
              <ComboboxOptionsError message={optionsError ?? ""} />
            ) : loading ? (
              <ComboboxOptionsSkeleton />
            ) : options.length === 0 ? (
              <div className="px-3 py-6 text-center text-muted-foreground text-xs">{emptyMessage}</div>
            ) : (
              <>
                <CommandEmpty>{noResultsMessage}</CommandEmpty>
                <CommandGroup>
                  {options.map((option) => {
                    const optionValue = String(option.value)
                    const isSelected = optionValue === current
                    return (
                      <CommandItem
                        key={optionValue}
                        value={optionSearchValue(option)}
                        disabled={option.disabled === true}
                        data-checked={isSelected || undefined}
                        onSelect={() => {
                          onValueChange(optionValue)
                          setOpen(false)
                        }}>
                        <CheckIcon className={cn("size-3.5 shrink-0", isSelected ? "opacity-100" : "opacity-0")} />
                        <ComboboxOptionRow
                          option={option}
                          truncateLabel={false}
                        />
                      </CommandItem>
                    )
                  })}
                </CommandGroup>
              </>
            )}
          </CommandList>
          {showClearFooter ? (
            <FieldClearSelectionFooter
              {...(clearLabel ? { label: clearLabel } : {})}
              onClear={clear}
            />
          ) : null}
        </Command>
      </PopoverContent>
    </Popover>
  )
}

export const FIELD_SIZES = ["sm", "default", "lg"] as const

export type FieldSize = (typeof FIELD_SIZES)[number]

export const FIELD_CONTROL_HEIGHT_CLASS: Record<FieldSize, string> = {
  sm: "h-6",
  default: "h-7",
  lg: "h-9",
}

export const FIELD_SKELETON_CONTROL_CLASS: Record<FieldSize, string> = {
  sm: "h-6 w-full",
  default: "h-7 w-full",
  lg: "h-9 w-full",
}

/** FormKit default: validate on submit, then revalidate on change. */
export const FORM_KIT_VALIDATION = {
  mode: "onSubmit",
  reValidateMode: "onChange",
  criteriaMode: "all",
  shouldFocusError: true,
} as const

"use client"

import type { FieldValues, Path } from "react-hook-form"
import type { CheckboxFieldProps } from "../field-types"

import { FieldPending } from "../field-pending"
import { FieldSlot } from "../field-slot"
import { useLazyField } from "../field-use-lazy"

const loadFieldCheckbox = () => import("./field-checkbox").then((mod) => mod.FieldCheckbox)

export function FieldCheckbox<TValues extends FieldValues, TName extends Path<TValues>>(
  props: CheckboxFieldProps<TValues, TName>,
) {
  const Comp = useLazyField("field-checkbox", loadFieldCheckbox)
  const { className, ...fieldProps } = props
  const id = String(props.name)

  return (
    <FieldSlot className={className}>
      {Comp == null || props.loading === true ? (
        <FieldPending
          id={id}
          label={props.label}
          description={props.description}
          helperText={props.helperText}
          required={props.required}
          size="sm"
          control="input"
        />
      ) : (
        <Comp {...(fieldProps as CheckboxFieldProps<FieldValues, Path<FieldValues>>)} />
      )}
    </FieldSlot>
  )
}

"use client"

import { FieldControlSkeleton } from "../field-control-skeleton"

export function FieldCheckboxSkeleton({ className }: { className?: string | undefined } = {}) {
  return (
    <FieldControlSkeleton
      size="sm"
      className={className}
    />
  )
}

"use client"

import type { FieldValues, Path } from "react-hook-form"
import type { CheckboxFieldProps } from "../field-types"

import { Controller, useFormContext } from "react-hook-form"

import { Checkbox } from "@/components/ui/checkbox"

import { FieldShell } from "../field-shell"
import { useFieldFlags } from "../field-use-flags"

export function FieldCheckbox<TValues extends FieldValues, TName extends Path<TValues>>(
  props: CheckboxFieldProps<TValues, TName>,
) {
  const { control } = useFormContext<TValues>()
  const { disabled, hidden } = useFieldFlags<TValues>({
    disabled: props.disabled,
    hidden: props.hidden,
  })
  const id = String(props.name)

  if (hidden) return null

  return (
    <Controller
      control={control}
      name={props.name}
      render={({ field, fieldState }) => {
        const invalid = fieldState.invalid
        return (
          <FieldShell
            id={id}
            label={props.label}
            description={props.description}
            helperText={props.helperText}
            required={props.required}
            disabled={disabled || props.readOnly}
            invalid={invalid}
            errorMessage={fieldState.error?.message}
            className={props.className}
            orientation="horizontal">
            <Checkbox
              id={id}
              name={id}
              checked={Boolean(field.value)}
              onCheckedChange={(checked) => field.onChange(checked === true)}
              disabled={disabled || props.readOnly}
              aria-invalid={invalid}
              aria-required={props.required}
              data-field-name={id}
            />
          </FieldShell>
        )
      }}
    />
  )
}

