            disabled={isDisabled}
            invalid={invalid}
            errorMessage={fieldState.error?.message}
            className={props.className}>
            <Popover
              open={open}
              onOpenChange={(next) => {
                if (isDisabled) return
                if (next) setYear(selected?.year ?? new Date().getFullYear())
                setOpen(next)
              }}>
              <PopoverTrigger asChild>
                <FieldPickerTrigger
                  id={id}
                  open={open}
                  disabled={isDisabled}
                  invalid={invalid}
                  required={props.required}
                  empty={empty}
                  size={size}
                  placeholder={props.placeholder ?? "Pick a quarter"}>
                  {label}
                </FieldPickerTrigger>
              </PopoverTrigger>
              <PopoverContent
                className="w-56 p-3"
                align="start">
                <div className="mb-3 flex items-center justify-between gap-2">
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon-sm"
                    disabled={year <= fromYear}
                    onClick={() => setYear((current) => Math.max(fromYear, current - 1))}>
                    <ChevronLeftIcon />
                  </Button>
                  <span className="font-medium text-sm tabular-nums">{year}</span>
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon-sm"
