function FormKitRoot<TSchema extends z.ZodTypeAny>({
  schema,
  defaultValues,
  onSubmit,
  isPending = false,
  resetOnSuccess = false,
  mapServerError = mapUnknownServerError,
  translateError,
  onSuccess,
  onError,
  className,
  scrollBody = true,
  children,
}: FormKitProps<TSchema>) {
  type InputValues = z.input<TSchema> & FieldValues
  type OutputValues = z.output<TSchema>

  const [actions, setActions] = useState<ReactNode>(null)

  const form = useForm<InputValues, unknown, OutputValues>({
    resolver: zodResolver(schema as never),
    defaultValues,
    ...FORM_KIT_VALIDATION,
  })

  const handleSubmit = form.handleSubmit(
    async (values) => {
      try {
        await onSubmit(values)
        onSuccess?.(values)
        if (resetOnSuccess === true) {
          form.reset(defaultValues)
        } else if (resetOnSuccess === "keepDirtyValues") {
          form.reset(values as InputValues, { keepDirtyValues: true })
        } else if (resetOnSuccess && typeof resetOnSuccess === "object") {
          form.reset(resetOnSuccess as InputValues)
        }
      } catch (error) {
        const mapped = mapServerError(error)
        const applied = applyServerErrors(form.setError, mapped)
        focusFirstError({ ...form.formState.errors, ...applied })
        onError?.(error)
      }
    },
    (errors) => {
      focusFirstError(errors)
    },
  )

  return (
    <FormProvider {...form}>
      <FormKitMetaProvider
        isPending={isPending}
        translateError={translateError}>
        <FormKitActionsContext value={setActions}>
          <form
            onSubmit={handleSubmit}
            className={cn(scrollBody ? FORM_KIT_ROOT_CLASS : "flex w-full flex-col", className)}
            noValidate>
            {scrollBody ? <FormKitScrollBody>{children}</FormKitScrollBody> : children}
            {actions}
          </form>
        </FormKitActionsContext>
      </FormKitMetaProvider>
    </FormProvider>
  )
}

function FormKitField<TValues extends FieldValues, TName extends Path<TValues>>(props: FormFieldProps<TValues, TName>) {
  return <FormFieldView {...props} />
}

function FormKitSubmit({ label = "Submit", pendingLabel = "Submitting…", className, disabled }: FormKitSubmitProps) {
  const { isPending } = useFormKitMeta()
  const { isSubmitting } = useFormState()
  const pending = isPending || isSubmitting

  return (
    <Button
      type="submit"
      disabled={disabled || pending}
      className={className}>
      {pending ? <Spinner className="size-4" /> : null}
      {pending ? pendingLabel : label}
    </Button>
  )
}

function FormKitReset({ label = "Reset", className, disabled }: FormKitResetProps) {
  const form = useFormContext()
  const { isPending } = useFormKitMeta()

  return (
    <Button
      type="button"
      variant="outline"
      disabled={disabled || isPending}
      className={className}
      onClick={() => form.reset()}>
      {label}
    </Button>
  )
}

function FormKitActions({ children, className }: { children: React.ReactNode; className?: string }) {
  const setActions = use(FormKitActionsContext)
  const [hydrated, setHydrated] = useState(false)

  useEffect(() => {
    setHydrated(true)
  }, [])

  useLayoutEffect(() => {
    if (!hydrated || !setActions) return

    setActions(<div className={cn(FORM_KIT_ACTIONS_CLASS, className)}>{children}</div>)
    return () => setActions(null)
  }, [hydrated, setActions, children, className])

  if (!setActions || !hydrated) {
    return <div className={cn(FORM_KIT_ACTIONS_CLASS, className)}>{children}</div>
  }

  return null
}

export const FormKit = Object.assign(FormKitRoot, {
  Field: FormKitField,
  Submit: FormKitSubmit,
  Reset: FormKitReset,
  Actions: FormKitActions,
})

import type { DateRange } from "react-day-picker"
import type { QuarterNumber } from "../constants/constants-date"

import { format, isValid, parse } from "date-fns"

import {
  DATE_ISO_PATTERN,
  DATE_ISO_PREFIX_PATTERN,
  DEFAULT_DATE_FROM_YEAR_OFFSET,
  DEFAULT_DATE_TO_YEAR_OFFSET,
  MONTH_ISO_PATTERN,
  QUARTER_ISO_PATTERN,
  QUARTER_LABELS,
  TIME_HM_PATTERN,
} from "../constants/constants-date"

export type DateRangeValue = {
  from?: string | undefined
  to?: string | undefined
}

function isDateInstance(value: unknown): value is Date {
  return value instanceof Date
}

function parseLocalYmd(value: string): Date | undefined {
  const parsed = parse(value, "yyyy-MM-dd", new Date())
  return isValid(parsed) ? parsed : undefined
}

/**
 * Calendar dates (`YYYY-MM-DD`) are local midnights — never UTC.
 * `parseISO("2024-01-15")` is UTC and shifts the day in negative-offset timezones.
 */
export function toDate(value: unknown): Date | undefined {
  if (value == null || value === "") return undefined
  if (isDateInstance(value)) return isValid(value) ? value : undefined
  if (typeof value !== "string") return undefined

  const trimmed = value.trim()
  if (DATE_ISO_PATTERN.test(trimmed)) {
    return parseLocalYmd(trimmed)
  }

  const ymd = DATE_ISO_PREFIX_PATTERN.exec(trimmed)?.[1]
  if (ymd) {
    return parseLocalYmd(ymd)
  }

  if (MONTH_ISO_PATTERN.test(trimmed)) {
    return parseLocalYmd(`${trimmed}-01`)
  }

  const fallback = new Date(trimmed)
  return isValid(fallback) ? fallback : undefined
}

export function toISODate(value: Date | undefined): string | undefined {
  if (!value || !isValid(value)) return undefined
  return format(value, "yyyy-MM-dd")
}

/** Platform `LocalDate` fields reject ISO datetimes — keep only `YYYY-MM-DD`. */
export function toLocalDateString(value: unknown): string {
  if (value == null || value === "") return ""
  if (typeof value === "string") {
    const trimmed = value.trim()
    if (DATE_ISO_PATTERN.test(trimmed)) return trimmed
    const ymd = DATE_ISO_PREFIX_PATTERN.exec(trimmed)?.[1]
    if (ymd) return ymd
  }
  return toISODate(toDate(value)) ?? ""
}

export function calendarNavRange(options?: {
  fromYear?: number | undefined
  toYear?: number | undefined
  minDate?: unknown
  maxDate?: unknown
}): { startMonth: Date; endMonth: Date } {
  const now = new Date()
  const fromYear = options?.fromYear ?? now.getFullYear() - DEFAULT_DATE_FROM_YEAR_OFFSET
  const toYear = options?.toYear ?? now.getFullYear() + DEFAULT_DATE_TO_YEAR_OFFSET
  let startMonth = new Date(fromYear, 0, 1)
  let endMonth = new Date(toYear, 11, 1)

  const min = toDate(options?.minDate)
  const max = toDate(options?.maxDate)
  if (min && min > startMonth) startMonth = new Date(min.getFullYear(), min.getMonth(), 1)
  if (max && max < endMonth) endMonth = new Date(max.getFullYear(), max.getMonth(), 1)
  if (startMonth > endMonth) {
    return { startMonth: endMonth, endMonth: startMonth }
  }
  return { startMonth, endMonth }
}

export function toISOMonth(value: Date | undefined): string | undefined {
  if (!value || !isValid(value)) return undefined
  return format(value, "yyyy-MM")
}

export function formatDateDisplay(value: unknown, displayFormat: string, empty = ""): string {
  const date = toDate(value)
  if (!date) return empty
  return format(date, displayFormat)
}

export function toDateRange(value: unknown): DateRange | undefined {
  if (value == null) return undefined

  if (typeof value === "object" && !Array.isArray(value)) {
    const record = value as Record<string, unknown>
    const from = toDate(record["from"] ?? record["start"])
    const to = toDate(record["to"] ?? record["end"])
    if (!from && !to) return undefined
    return { from, to }
  }

  return undefined
}

export function toDateRangeValue(range: DateRange | undefined): DateRangeValue | undefined {
  if (!range?.from && !range?.to) return undefined
  return {
    from: toISODate(range.from),
    to: toISODate(range.to),
  }
}

export function formatDateRangeDisplay(value: unknown, displayFormat: string, empty = ""): string {
  const range = toDateRange(value)
  if (!range?.from) return empty
  if (!range.to) return format(range.from, displayFormat)
  return `${format(range.from, displayFormat)} – ${format(range.to, displayFormat)}`
}

export function toTimeValue(value: unknown): string {
  if (value == null || value === "") return ""
  if (typeof value === "string" && TIME_HM_PATTERN.test(value)) {
    return value.slice(0, 5)
  }
  if (isDateInstance(value) && isValid(value)) {
    return format(value, "HH:mm")
  }
  return ""
}

export function quarterFromDate(date: Date): QuarterNumber {
  return (Math.floor(date.getMonth() / 3) + 1) as QuarterNumber
}

export function parseQuarter(value: unknown): { year: number; quarter: QuarterNumber } | undefined {
  if (typeof value !== "string" || !QUARTER_ISO_PATTERN.test(value)) return undefined
  const [yearPart, quarterPart] = value.split("-Q")
  const year = Number(yearPart)
  const quarter = Number(quarterPart) as QuarterNumber
  if (!Number.isInteger(year) || quarter < 1 || quarter > 4) return undefined
  return { year, quarter }
}

export function toISOQuarter(year: number, quarter: QuarterNumber): string {
  return `${year}-Q${quarter}`
}

export function formatQuarterDisplay(value: unknown, empty = ""): string {
  const parsed = parseQuarter(value)
  if (!parsed) return empty
  return `${QUARTER_LABELS[parsed.quarter]} ${parsed.year}`
}

export function monthStart(year: number, monthIndex: number): Date {
  return new Date(year, monthIndex, 1)
}

export function disabledMatcher(minDate?: unknown, maxDate?: unknown) {
  const min = toDate(minDate)
  const max = toDate(maxDate)
  if (!min && !max) return undefined
  return (date: Date) => {
    if (min) {
      const start = new Date(min.getFullYear(), min.getMonth(), min.getDate())
      if (date < start) return true
    }
    if (max) {
      const end = new Date(max.getFullYear(), max.getMonth(), max.getDate())
      if (date > end) return true
    }
    return false
  }
}

import type { FieldValues } from "react-hook-form"
import type { FieldContext, FieldFlag } from "../field/field-types"

export function resolveFieldFlag<TValues extends FieldValues>(
  flag: FieldFlag<TValues> | undefined,
  ctx: FieldContext<TValues>,
  fallback = false,
): boolean {
  if (flag === undefined) return fallback
  if (typeof flag === "function") return flag(ctx)
  return flag
}

import type { FieldErrors, FieldValues } from "react-hook-form"

function collectErrorPaths(errors: FieldErrors<FieldValues>, prefix = ""): string[] {
  const paths: string[] = []
  for (const [key, value] of Object.entries(errors)) {
    if (!value || typeof value !== "object") continue
    const path = prefix ? `${prefix}.${key}` : key
    if ("message" in value && value.message) {
      paths.push(path)
      continue
    }
    paths.push(...collectErrorPaths(value as FieldErrors<FieldValues>, path))
  }
  return paths
}

/** Focus the first invalid control by name attribute / id convention. */
export function focusFirstError(errors: FieldErrors<FieldValues>): void {
  const paths = collectErrorPaths(errors)
  const first = paths[0]
  if (!first) return

  const escaped = CSS.escape(first)
  const el =
    (document.querySelector(`[name="${escaped}"]`) as HTMLElement | null) ??
    (document.getElementById(first) as HTMLElement | null) ??
    (document.querySelector(`[data-field-name="${escaped}"]`) as HTMLElement | null)

  if (!el) return
  el.scrollIntoView({ block: "center", behavior: "smooth" })
  if (typeof el.focus === "function") {
    el.focus({ preventScroll: true })
  }
}

import type { FieldErrors, FieldValues, UseFormSetError } from "react-hook-form"
import type { MapServerErrorResult, ServerFieldError } from "../field/field-types"

function normalizeServerErrors(result: MapServerErrorResult): {
  form?: string
  fields: ServerFieldError[]
} {
  if (Array.isArray(result)) {
    return { fields: result }
  }
  const normalized: { form?: string; fields: ServerFieldError[] } = {
    fields: result.fields ?? [],
  }
  if (result.form) normalized.form = result.form
  return normalized
}

export function applyServerErrors<TValues extends FieldValues>(
  setError: UseFormSetError<TValues>,
  result: MapServerErrorResult,
): FieldErrors<TValues> {
  const { form, fields } = normalizeServerErrors(result)
  const applied: FieldErrors<TValues> = {}

  if (form) {
    setError("root.server" as never, { type: "server", message: form })
  }

  for (const field of fields) {
    setError(field.path as never, {
      type: "server",
      message: field.message,
    })
    ;(applied as Record<string, { message: string; type: string }>)[field.path] = {
      type: "server",
      message: field.message,
    }
  }

  return applied
}

/** Best-effort map for common tRPC / Zod flatten shapes. */
export function mapUnknownServerError(error: unknown): MapServerErrorResult {
  if (!error || typeof error !== "object") {
    return { form: "Something went wrong. Please try again." }
  }

  const record = error as {
    message?: string
    data?: {
      zodError?: {
        fieldErrors?: Record<string, string[] | undefined>
        formErrors?: string[]
      }
      flat?: {
        fieldErrors?: Record<string, string[] | undefined>
        formErrors?: string[]
      }
    }
  }

  const fieldErrors = record.data?.zodError?.fieldErrors ?? record.data?.flat?.fieldErrors ?? undefined
  const formErrors = record.data?.zodError?.formErrors ?? record.data?.flat?.formErrors ?? undefined

  const fields: ServerFieldError[] = []
  if (fieldErrors) {
    for (const [path, messages] of Object.entries(fieldErrors)) {
      const message = messages?.[0]
      if (message) fields.push({ path, message })
    }
  }

  const formMessage = formErrors?.[0] ?? (fields.length === 0 ? record.message : undefined)
  const result: MapServerErrorResult = { fields }
  if (formMessage) {
    return { form: formMessage, fields }
  }
  return result
}

/** Resolve Zod / server error text; `translateError` maps i18n keys to locale strings. */
export function resolveFieldErrorMessage(
  message: string | undefined,
  translateError?: ((message: string) => string) | undefined,
): string | undefined {
  if (!message) {
    return undefined
  }

  return translateError?.(message) ?? message
}
